sp_widget.client_script:
api.controller = function($scope, spUtil, $timeout) {
  var c = this;

  c.isLoading = false;
  c.userMessage = '';
  c.showResponseWidget = false;
  c.responseWidget = null;

  // ✅ Extract IPs from traceroute output (only from numbered lines)
  function extractIPAddresses(traceOutput) {
    var lines = traceOutput.split('\n');
    var ipRegex = /\b(?:\d{1,3}\.){3}\d{1,3}\b/;
    var ipList = [];

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i].trim();
      if (/^\d+\s/.test(line)) { // Line starts with hop number
        var match = line.match(ipRegex);
        if (match && match[0] !== '0.0.0.0') {
          ipList.push(match[0]);
        }
      }
    }

    return ipList;
  }

  // ✅ Match extracted IPs with location data
  function filterLocationsByIPs(ipList, allLocations) {
    if (!Array.isArray(allLocations)) return [];

    var matched = [];

    for (var i = 0; i < ipList.length; i++) {
      var ip = ipList[i].trim();

      for (var j = 0; j < allLocations.length; j++) {
        var locIP = allLocations[j].ip ? allLocations[j].ip.trim() : '';
        if (ip === locIP) {
          matched.push(allLocations[j]);
          break;
        }
      }
    }

    return matched;
  }

  // ✅ Trigger visualization
  c.sendMessage = function() {
    if (!c.userMessage || !c.userMessage.trim()) {
      alert('Please paste traceroute output first.');
      return;
    }

    c.isLoading = true;

    $timeout(function() {
      var ipList = extractIPAddresses(c.userMessage);
      if (!ipList.length) {
        c.isLoading = false;
        alert('No IP addresses found.');
        return;
      }

      if (!c.data || !Array.isArray(c.data.locations)) {
        c.isLoading = false;
        alert('Location data not loaded.');
        return;
      }

      var matchedLocations = filterLocationsByIPs(ipList, c.data.locations);
      if (!matchedLocations.length) {
        c.isLoading = false;
        alert('No matching IP data found.');
        return;
      }

      console.log('📦 Sending matched locations to widget:', matchedLocations);

      spUtil.get('cd98ce74837222100daa76d6feaad378', {
        locations: JSON.stringify(matchedLocations)
      }).then(function(widgetResponse) {
        c.responseWidget = widgetResponse;
        c.showResponseWidget = true;
        c.isLoading = false;
        $scope.$applyAsync();
      });
    }, 100);
  };

  // ✅ Reset input and UI
  c.resetInput = function() {
    c.userMessage = '';
    c.showResponseWidget = false;
    c.responseWidget = null;
  };
};

sp_widget.css:
body {
  margin: 0;
  padding: 40px;
  background: linear-gradient(to right, #e3eaf6, #f8f9fb);
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  color: #333;
}

.container {
  max-width: 800px;
  margin: 0 auto;
  background-color: #ffffff;
  padding: 30px;
  border-radius: 16px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.08);
  transition: box-shadow 0.3s ease;
}

.container:hover {
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.12);
}

textarea {
  width: 100%;
  height: 300px;
  resize: none;
  font-size: 16px;
  padding: 15px;
  box-sizing: border-box;
  border: 1px solid #d0d7e2;
  border-radius: 10px;
  background-color: #f9fbff;
  outline: none;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

textarea:focus {
  border-color: #4a90e2;
  box-shadow: 0 0 0 4px rgba(74, 144, 226, 0.2);
  background-color: #ffffff;
}

.button-row {
  display: flex;
  justify-content: flex-end;
  margin-top: 20px;
  gap: 12px;
}

button {
  padding: 12px 26px;
  font-size: 15px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  background: linear-gradient(135deg, #4a90e2, #357ab8);
  color: #fff;
  box-shadow: 0 4px 12px rgba(74, 144, 226, 0.3);
  transition: background 0.3s ease, box-shadow 0.3s ease, transform 0.2s;
}

button:hover {
  background: linear-gradient(135deg, #357ab8, #2c6cb0);
  box-shadow: 0 6px 18px rgba(74, 144, 226, 0.4);
  transform: translateY(-2px);
}

button:active {
  transform: scale(0.98);
}

.loader {
  text-align: center;
  margin-top: 20px;
}

.spinner {
  border: 4px solid #ccc;
  border-top: 4px solid #007bff;
  border-radius: 50%;
  width: 30px;
  height: 30px;
  animation: spin 1s linear infinite;
  display: inline-block;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

textarea[disabled] {
  background-color: #f0f0f0;
  cursor: not-allowed;
}

button[disabled] {
  opacity: 0.6;
  cursor: not-allowed;
}

sp_widget.script:
(function() {
  var edgeGR = new GlideRecord("x_688732_custom_ap_enterprise_edge_details");
  edgeGR.addEncodedQuery("enterprise_id=9^edge_id=32");
  edgeGR.query();

  if (edgeGR.next()) {
    try {
      data.locations = JSON.parse(edgeGR.ips_lat_lon_host); // assuming it's a JSON string
    } catch (e) {
      data.locations = [];
    }
  } else {
    data.locations = [];
  }
})();
